arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Content-Type: application/json' -d '{"token":"***","types":"public_channel,private_channel","exclude_archived":false,"limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR:', d.get('error')); sys.exit()
for c in d['channels']:
    if 'incident' in c['name'].lower() or 'checkout' in c['name'].lower() or 'outage' in c['name'].lower():
        print(c['id'], c['name'], 'archived' if c.get('is_archived') else 'active')
"

